Definition iarm_0RB1LA_1RC1RD_0LA0LA_1RB1LC (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LA_1RC1RD_0LA0LA_1RB1LC
  | 0, 1 => iarm0_1_0RB1LA_1RC1RD_0LA0LA_1RB1LC
  | 1, 0 => iarm1_0_0RB1LA_1RC1RD_0LA0LA_1RB1LC
  | 1, 1 => iarm1_1_0RB1LA_1RC1RD_0LA0LA_1RB1LC
