Import WrapTr LadderCheckTr.
Import LapGlueTr.
Import LadderCheckLiftTr.
Import ListNotations.

Definition mk_0RB1LA_1RC1RD_0RD1RB_1LD0LA (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_0RB1LA_1RC1RD_0RD1RB_1LD0LA.

(** 0RB1LA_1RC1RD_0RD1RB_1LD0LA *)
Definition tm_0RB1LA_1RC1RD_0RD1RB_1LD0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB
  | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S0 DR StD
  | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S1 DL StD
  | StD, S1 => mk S0 DL StA
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_0RB1LA_1RC1RD_0RD1RB_1LD0LA : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_0RB1LA_1RC1RD_0RD1RB_1LD0LA pins_0RB1LA_1RC1RD_0RD1RB_1LD0LA).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB1LA_1RC1RD_0RD1RB_1LD0LA : Fam := mkFam 3 [[S1;S1];[S1;S0];[S0;S1]] [] [[]] Binary 1 [mkFill 2 [] 0 [2;1] 0] StA S0 false [].
Local Notation FAM := fam_0RB1LA_1RC1RD_0RD1RB_1LD0LA.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB1LA_1RC1RD_0RD1RB_1LD0LA : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StC (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_0RB1LA_1RC1RD_0RD1RB_1LD0LA.

Definition rules_0RB1LA_1RC1RD_0RD1RB_1LD0LA : list LRule := map fst lad.
Local Notation rules := rules_0RB1LA_1RC1RD_0RD1RB_1LD0LA.

Lemma ladder_ok_0RB1LA_1RC1RD_0RD1RB_1LD0LA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1LA_1RC1RD_0RD1RB_1LD0LA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1LA_1RC1RD_0RD1RB_1LD0LA. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* A[0] L<> R<01^1+y0>  ==>  A[0] L<> R<1^2+2*y0 0^1 1^2>   [10+4*y0 steps] *)
Definition arm23_0RB1LA_1RC1RD_0RD1RB_1LD0LA : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S0;S1;S0;S1] [S0;S1] 1 0 []))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1;S1;S1;S1] [S1;S1] 1 0 [S0;S1;S1])) 4 18.
Definition ch_arm23_0RB1LA_1RC1RD_0RD1RB_1LD0LA : list rstep := [RB (SWin 6);RB (SCycR 2);RB (SWinR 6);RB (SCycL 2 0);RB (SWin 6)].
Lemma ok_arm23_0RB1LA_1RC1RD_0RD1RB_1LD0LA :
  check_arm tm true true rules arm23_0RB1LA_1RC1RD_0RD1RB_1LD0LA ch_arm23_0RB1LA_1RC1RD_0RD1RB_1LD0LA = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm23_0RB1LA_1RC1RD_0RD1RB_1LD0LA : RuleSound tm true true arm23_0RB1LA_1RC1RD_0RD1RB_1LD0LA.
Proof. eapply arm_sound; [exact rules_sound_0RB1LA_1RC1RD_0RD1RB_1LD0LA | exact ok_arm23_0RB1LA_1RC1RD_0RD1RB_1LD0LA]. Qed.

