  check_arm tm true false rules iarm1_0_0RB1LA_1RC1RD_0RD1RB_1LD0LA
            ch_iarm1_0_0RB1LA_1RC1RD_0RD1RB_1LD0LA = true.
Proof. vm_compute. reflexivity. Qed.

