Proof. vm_compute. reflexivity. Qed.

Definition iarm_0RB1LA_1RC1RD_0RD1RB_1LD0LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LA_1RC1RD_0RD1RB_1LD0LA
  | 0, 1 => iarm0_1_0RB1LA_1RC1RD_0RD1RB_1LD0LA
  | 1, 0 => iarm1_0_0RB1LA_1RC1RD_0RD1RB_1LD0LA
  | 1, 1 => iarm1_1_0RB1LA_1RC1RD_0RD1RB_1LD0LA
  | _, _ => iarm0_0_0RB1LA_1RC1RD_0RD1RB_1LD0LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_0RB1LA_1RC1RD_0RD1RB_1LD0LA : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 []))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1;S1] 1 0 [S0;S1;S1])) 4 10.
Definition ch_farm1_0_0RB1LA_1RC1RD_0RD1RB_1LD0LA : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWinR 6);RB (SCycL 2 0);RB (SWin 2)].
