Definition iarm_0RB1LA_1RC1RD_1LA1RB_1LD0LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LA_1RC1RD_1LA1RB_1LD0LA
  | 0, 1 => iarm0_1_0RB1LA_1RC1RD_1LA1RB_1LD0LA
  | 1, 0 => iarm1_0_0RB1LA_1RC1RD_1LA1RB_1LD0LA
  | 1, 1 => iarm1_1_0RB1LA_1RC1RD_1LA1RB_1LD0LA
  | _, _ => iarm0_0_0RB1LA_1RC1RD_1LA1RB_1LD0LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

