Lemma fm12_0RB1LA_1RC1RD_1LA1RB_1LD0LA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  fm1_0RB1LA_1RC1RD_1LA1RB_1LD0LA r ph + fm2_0RB1LA_1RC1RD_1LA1RB_1LD0LA r ph
  + (length (f_pre (fam_fill FAM ph)) + length (f_suf (fam_fill FAM ph)))
